				accent = Color3.fromRGB(16, 185, 129), accentText = Color3.fromRGB(110, 231, 183),
				text = Color3.fromRGB(231, 246, 237), subText = Color3.fromRGB(148, 182, 162), muted = Color3.fromRGB(96, 128, 108),
			},
